<script setup lang="ts">
const platformApi = uni
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {useUserStore} from '../../store/modules/user';import {time,toast,confirm} from '../../utils/format';const user=useUserStore(),orders=ref<any[]>([]),orderId=ref(0),content=ref(''),hospitals=ref<any[]>([]),tickets=ref<any[]>([]);onLoad(q=>orderId.value=Number(q?.orderId||0));const {loading,error,load,busy,action}=usePage(async()=>{orders.value=(await request('/orders?size=100')).list;tickets.value=(await request('/emergencies/mine?size=100')).list});async function send(){if(!orderId.value||!content.value.trim())return toast('请选择关联订单并描述异常');await request('/emergencies','POST',{orderId:orderId.value,content:content.value});content.value='';await load()}async function consent(id:number){if(await confirm('您明确授权平台协助将本次订单中的宠物送往医院？医疗方案仍需与医院确认。')){await request('/emergencies/'+id+'/consent','POST');await load()}}async function nearby(){const o=orders.value.find(o=>o.id===orderId.value);if(!o)return toast('请先选择订单，以服务地址查询附近医院');hospitals.value=await request('/hospitals/nearby?longitude='+o.address_snapshot.longitude+'&latitude='+o.address_snapshot.latitude)}
</script><template><PageShell title="应急帮助与送医协助" back :loading="loading" :error="error" @retry="load"><view class="hero" style="background:#fbe3e0"><view class="hero-title">发现异常，<br/>及时求助。</view><text class="subtitle">描述现场情况，平台将跟进处理。<br/>危急情况请直接联系附近宠物医院。</text></view><view class="card"><text class="label">关联服务订单</text><picker :range="orders" range-key="order_no" @change="orderId=orders[Number($event.detail.value)].id"><view class="field" style="padding:12px">{{orderId?'订单 #'+orderId:'选择订单'}} ›</view></picker><text class="label">异常情况</text><view class="field field-area"><textarea v-model="content" maxlength="2000" placeholder="描述拒食、呕吐、受伤等情况及发生时间，请勿自行作医疗判断。"/></view><button class="primary" :disabled="busy" @click="action(send,'应急工单已提交')">提交应急求助</button><button class="outline full-width" style="margin-top:12px" @click="action(nearby,'')">查看服务地址附近医院</button></view><view class="card" v-for="h in hospitals" :key="h.id"><view class="row"><text>{{h.name}}</text><text class="pill">{{Number(h.distanceKm).toFixed(1)}} km</text></view><text class="muted">{{h.address}}</text><view class="link" @click="platformApi.makePhoneCall({phoneNumber:h.phone})">{{h.phone}} · 点击拨号</view></view><view class="section">求助进展</view><view class="card" v-for="t in tickets" :key="t.id"><view>{{t.content}}</view><text class="muted">{{time(t.created_at)}} · {{t.status==='OPEN'?'待受理':t.status==='ACCEPTED'?'已受理':t.status==='TRANSPORTING'?'送医中':'已处理'}}</text><view v-if="t.resolution">{{t.resolution}}</view><button v-if="!user.sitter&&!t.owner_consent&&t.status!=='RESOLVED'" class="secondary" style="margin-top:12px" @click="action(()=>consent(t.id),'')">明确授权送医协助</button><view v-if="t.owner_consent" class="pill green">宠主已授权送医</view></view></PageShell></template>

